/bin/bash -lc "node --input-type=module <<'EOF'
import {mkdir,writeFile} from 'node:fs/promises';
const response = await fetch('https://fonts.googleapis.com/css2?family=Golos+Text:wght@400..800&display=swap',{headers:{'User-Agent':'Mozilla/5.0 Chrome/120.0.0.0 Safari/537.36'}});
if("'!response.ok) throw new Error('"'Font stylesheet unavailable');
let css = await response.text();
const urls = [...new Set([...css.matchAll(/url\\((https:["'^)]+)'"\\)/g)].map(match=>match[1]))];
await mkdir('public/fonts',{recursive:true});
for(const [index,url] of urls.entries()){
 const font = await fetch(url); if("'!font.ok) throw new Error('"'Font unavailable');
 const name = "'`golos-${index}.${url.includes('"'.woff2')?'woff2':'ttf'}"'`;
 await writeFile(`public/fonts/${name}`,Buffer.from(await font.arrayBuffer()));
 css = css.replaceAll(url,`/fonts/${name}`);
}
await writeFile('"'public/fonts/golos.css',css);
console.log("'`Downloaded ${urls.length} local font assets`);
EOF'

